CREATE DATABASE IF NOT EXISTS arenax CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE arenax;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('player','super_admin','finance','tournament','support','moderator','analyst') NOT NULL DEFAULT 'player', coins BIGINT NOT NULL DEFAULT 0, status ENUM('active','suspended','banned') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coin_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,delta BIGINT NOT NULL,kind ENUM('topup','entry','prize','refund','adjustment') NOT NULL,reference VARCHAR(100) NOT NULL,note VARCHAR(255),admin_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_user_kind_ref(user_id,kind,reference),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS topup_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,amount_paise INT UNSIGNED NOT NULL,coins BIGINT UNSIGNED NOT NULL,utr VARCHAR(100) NOT NULL,screenshot_path VARCHAR(255) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',admin_note VARCHAR(255),reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_utr(utr),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tournaments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(140) NOT NULL,game VARCHAR(60) NOT NULL,mode VARCHAR(40) NOT NULL,description TEXT,entry_coins INT UNSIGNED NOT NULL DEFAULT 0,prize_coins BIGINT UNSIGNED NOT NULL DEFAULT 0,max_teams INT UNSIGNED NOT NULL DEFAULT 64,starts_at DATETIME NOT NULL,status ENUM('draft','upcoming','live','completed','cancelled') NOT NULL DEFAULT 'draft',room_id VARCHAR(100),room_password VARCHAR(100),created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tournament_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,team_name VARCHAR(100),status ENUM('registered','checked_in','disqualified','completed') NOT NULL DEFAULT 'registered',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_entry(tournament_id,user_id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS match_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,placement INT UNSIGNED,kills INT UNSIGNED DEFAULT 0,points INT DEFAULT 0,proof_path VARCHAR(255),status ENUM('pending','approved','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject VARCHAR(180) NOT NULL,message TEXT NOT NULL,status ENUM('open','in_progress','resolved','closed') DEFAULT 'open',assigned_to BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT UNSIGNED NULL,details JSON NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES users(id)) ENGINE=InnoDB;
